INSERT INTO roles(code,name) VALUES('SUPER_ADMIN','Super Admin'),('ADMIN','Admin'),('SUPERVISOR','Supervisor'),('STAFF','Staff');
INSERT INTO permissions(code,description) VALUES('employee.view','View employees'),('employee.create','Create employees'),('employee.update','Update employees'),('employee.deactivate','Deactivate employees'),('training.view','View training'),('training.create','Create training'),('schedule.view','View schedules'),('schedule.create','Create schedules'),('attendance.record','Record attendance'),('score.create','Create scores'),('report.view','View reports'),('report.export','Export reports'),('import.execute','Execute imports'),('telegram.manage','Manage Telegram'),('audit.view','View audit'),('settings.manage','Manage settings');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN';